	lidx := dimension[0]
	if s.numLanguages > 0 {
		lidx = s.dimensionLanguageIndex(dimension)
	}
	switch v := n.(type) {
	case contentNodeIs:
		resource.MarkStale(v[lidx])
		wasDeleted := v[lidx] != nil
		v[lidx] = nil
		return wasDeleted, s.languageSlotEmpty(v)
	case resourceSources:
		resource.MarkStale(v[lidx])
		wasDeleted := v[lidx] != nil
		v[lidx] = nil
		return wasDeleted, s.resourceSlotEmpty(v)
